#include "sio_uart_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

Boolean sio_uart_fifo_rx_append_i (Sio_Uart sio_uart , SInt16 data)
{
  MbxMsg * rx_data = os_mbx_rcev_i (sio_uart->rx.q_free) ;

  if (rx_data)
    {
      cast_mbx_msg_to_sio_rx_data (rx_data)->data = data ;

      os_mbx_send_i (sio_uart->rx.q_rcev , rx_data) ;
    }

  return !! rx_data ;
}

